#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as dt
import importlib.util
import os
import py_compile
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

VERSION = "0.14.0-rebase1"

MODIFIED_B64 = {'backend/app/api/v1/endpoints/vision_app_api.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/automation_manager.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/automation_models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/camera_resource_runtime.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/endpoint_registry.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/repository.py': {'old': '', 'new': ''}, 'frontend/src/Pages/ComputerVisionPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/visionAppApi.ts': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/AutomationCodeEditor.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/CameraDeclarationWorkspace.tsx': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64 = {'backend/app/services/vision_app/streaming_runtime.py': '', 'backend/tests/vision_app/test_vision_app_v1400.py': '', 'frontend/docs/llm_context/updates/v1400_streaming_soft_trigger.md': '', 'frontend/src/components/ComputerVision/StreamingWorkspace.tsx': ''}

MODIFIED = {
    path: {
        "old": base64.b64decode(payload["old"]).decode("utf-8"),
        "new": base64.b64decode(payload["new"]).decode("utf-8"),
    }
    for path, payload in MODIFIED_B64.items()
}
CREATED = {
    path: base64.b64decode(payload).decode("utf-8")
    for path, payload in CREATED_B64.items()
}


def resolve_roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()
    fe_candidates = []
    be_candidates = []

    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())

    fe_candidates += [
        cwd,
        cwd / "LambdaVisionSuper",
        cwd.parent / "LambdaVisionSuper",
    ]
    be_candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    frontend = next(
        (
            p for p in fe_candidates
            if (p / "src/Pages/ComputerVisionPage.tsx").exists()
            and (p / "src/components/ComputerVision/WorkspaceTabs.tsx").exists()
        ),
        None,
    )
    backend = next(
        (
            p for p in be_candidates
            if (p / "app/services/vision_app/automation_manager.py").exists()
            and (p / "app/services/vision_app/models.py").exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuper frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )
    if backend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuperBackEnd. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )

    return frontend, backend


def real_path(frontend: Path, backend: Path, virtual: str) -> Path:
    if virtual.startswith("frontend/"):
        return frontend / virtual[len("frontend/"):]
    if virtual.startswith("backend/"):
        return backend / virtual[len("backend/"):]
    raise ValueError(virtual)


def three_way_merge(current: str, old: str, new: str):
    """
    Merge current-user-tree changes with v0.14 desired changes using:
      ours   = current
      base   = old v0.13.5 baseline
      theirs = v0.14 desired
    Return (state, merged_text, diagnostics)
    """
    if current == new:
        return "OK", current, ""
    if current == old:
        return "UPDATE", new, ""

    with tempfile.TemporaryDirectory(prefix="lambda_v1400_merge_") as tmp:
        root = Path(tmp)
        ours = root / "current.txt"
        base = root / "base.txt"
        theirs = root / "v1400.txt"
        ours.write_text(current, encoding="utf-8")
        base.write_text(old, encoding="utf-8")
        theirs.write_text(new, encoding="utf-8")

        proc = subprocess.run(
            [
                "git",
                "merge-file",
                "-p",
                "--diff3",
                "-L",
                "CURRENT_TREE",
                "-L",
                "V0.13.5_BASE",
                "-L",
                "V0.14_DESIRED",
                str(ours),
                str(base),
                str(theirs),
            ],
            text=True,
            capture_output=True,
        )

        if proc.returncode == 0:
            return "MERGE", proc.stdout, proc.stderr.strip()

        if proc.returncode == 1:
            return "CONFLICT", proc.stdout, proc.stderr.strip()

        return (
            "ERROR",
            "",
            (proc.stdout + "\n" + proc.stderr).strip(),
        )


def modified_state(path: Path, old: str, new: str):
    if not path.exists():
        return "MISSING", None, ""
    current = path.read_text(encoding="utf-8")
    return three_way_merge(current, old, new)


def created_state(path: Path, desired: str) -> str:
    if not path.exists():
        return "CREATE"
    if path.read_text(encoding="utf-8") == desired:
        return "OK"
    return "CONFLICT"


def scan(frontend: Path, backend: Path):
    print("=" * 118)
    print("COMPUTER VISION V0.14.0 — STREAMING / SOFT TRIGGER — THREE-WAY REBASE INSTALLER")
    print("=" * 118)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    blockers = 0
    merge_count = 0

    for virtual, payload in MODIFIED.items():
        state, _, diag = modified_state(
            real_path(frontend, backend, virtual),
            payload["old"],
            payload["new"],
        )
        print(f"  [{state:12}] {virtual}")
        if state == "MERGE":
            merge_count += 1
        elif state not in {"UPDATE", "OK"}:
            blockers += 1
            if diag:
                print("                 " + diag.replace("\n", "\n                 "))

    for virtual, desired in CREATED.items():
        state = created_state(
            real_path(frontend, backend, virtual),
            desired,
        )
        print(f"  [{state:12}] {virtual}")
        if state not in {"CREATE", "OK"}:
            blockers += 1

    print()
    print("Meaning:")
    print("  UPDATE   = exact v0.13.5 baseline; replace with v0.14 version")
    print("  MERGE    = current tree has local/hotfix differences; automatic 3-way merge is clean")
    print("  OK       = v0.14 content already present")
    print("  CONFLICT = local changes overlap the v0.14 edit; updater will NOT apply")
    print()
    print("v0.14 features preserved:")
    print("  Basler backend streaming -> Streaming_frame")
    print("  Lazy browser preview")
    print("  Workspace Soft Trigger ROI / threshold / hysteresis")
    print("  ONLINE auto-arms enabled Soft Triggers")
    print("  keyboard.key.A..Z + numeric/numpad/special/F1..F12")
    print("  HTTP/Raspberry Pi streaming transport remains pending scaffold")

    if blockers:
        print()
        print(f"[WARN] {blockers} blocking issue(s). Do not apply.")
    else:
        print()
        print(f"[OK] Safe to apply. {merge_count} file(s) will be 3-way merged.")

    return 0 if blockers == 0 else 1


def preflight(frontend: Path, backend: Path):
    errors = []

    for virtual, payload in MODIFIED.items():
        state, _, diag = modified_state(
            real_path(frontend, backend, virtual),
            payload["old"],
            payload["new"],
        )
        if state not in {"UPDATE", "MERGE", "OK"}:
            detail = f"{virtual}: {state}"
            if diag:
                detail += f" ({diag.splitlines()[0]})"
            errors.append(detail)

    for virtual, desired in CREATED.items():
        state = created_state(
            real_path(frontend, backend, virtual),
            desired,
        )
        if state not in {"CREATE", "OK"}:
            errors.append(f"{virtual}: {state}")

    if errors:
        raise RuntimeError(
            "Safe rebase stopped:\n  - " + "\n  - ".join(errors)
        )


def backup(frontend: Path, backend: Path, paths: list[Path]) -> Path:
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    root = (
        frontend
        / ".lambda_updater_backups"
        / f"computer_vision_v1400_rebase_{stamp}"
    )
    root.mkdir(parents=True, exist_ok=True)

    for path in paths:
        if not path.exists():
            continue
        try:
            rel = path.relative_to(frontend)
            destination = root / "frontend" / rel
        except ValueError:
            rel = path.relative_to(backend)
            destination = root / "backend" / rel

        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, destination)

    return root


def regenerate_context(frontend: Path, backend: Path):
    generator = frontend / "tools/generate_llm_context_map.py"
    if not generator.exists():
        print("[SKIP] Context generator not found")
        return

    cmd = [
        sys.executable,
        str(generator),
        "--frontend",
        str(frontend),
        "--backend",
        str(backend),
    ]

    if "--output-dir" in generator.read_text(encoding="utf-8"):
        cmd.extend(
            [
                "--output-dir",
                str(frontend / "docs/llm_context"),
            ]
        )

    proc = subprocess.run(
        cmd,
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )

    if proc.returncode != 0:
        raise RuntimeError(
            "Context generator failed:\n"
            + (proc.stdout + "\n" + proc.stderr).strip()
        )

    if proc.stdout.strip():
        print(proc.stdout.strip())


def apply(frontend: Path, backend: Path):
    preflight(frontend, backend)

    targets = [
        real_path(frontend, backend, key)
        for key in list(MODIFIED) + list(CREATED)
    ]
    backup_root = backup(frontend, backend, targets)

    for virtual, payload in MODIFIED.items():
        path = real_path(frontend, backend, virtual)
        current = path.read_text(encoding="utf-8")
        state, merged, diag = three_way_merge(
            current,
            payload["old"],
            payload["new"],
        )

        if state == "OK":
            print(f"[KEEP ] {virtual}")
            continue

        if state not in {"UPDATE", "MERGE"}:
            raise RuntimeError(
                f"Unexpected state during apply for {virtual}: {state}\n{diag}"
            )

        path.write_text(merged, encoding="utf-8")
        print(f"[{state:5}] {virtual}")

    for virtual, desired in CREATED.items():
        path = real_path(frontend, backend, virtual)
        path.parent.mkdir(parents=True, exist_ok=True)

        if not path.exists():
            path.write_text(desired, encoding="utf-8")
            print(f"[CREATE] {virtual}")
        elif path.read_text(encoding="utf-8") == desired:
            print(f"[KEEP ] {virtual}")
        else:
            raise RuntimeError(
                f"Created-file collision during apply: {virtual}"
            )

    print("[INFO] Regenerating LLM context docs...")
    regenerate_context(frontend, backend)

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def typescript_transpile(frontend: Path):
    files = [
        real_path(frontend, Path("/unused"), virtual)
        for virtual in list(MODIFIED) + list(CREATED)
        if virtual.startswith("frontend/")
        and virtual.endswith((".ts", ".tsx"))
    ]

    code = r"""
const fs = require("fs");
const ts = require("typescript");
let failed = false;

for (const file of process.argv.slice(1)) {
  const source = fs.readFileSync(file, "utf8");
  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });

  const errors = (result.diagnostics || []).filter(
    (d) => d.category === ts.DiagnosticCategory.Error,
  );

  if (errors.length) {
    failed = true;
    console.error("TS_ERROR", file);
    for (const d of errors) {
      console.error(
        ts.flattenDiagnosticMessageText(d.messageText, "\n"),
      );
    }
  }
}

process.exit(failed ? 1 : 0);
"""

    env = dict(os.environ)
    npm_root = subprocess.run(
        ["npm", "root", "-g"],
        text=True,
        capture_output=True,
    )

    if npm_root.returncode == 0 and npm_root.stdout.strip():
        env["NODE_PATH"] = npm_root.stdout.strip() + (
            os.pathsep + env["NODE_PATH"]
            if env.get("NODE_PATH")
            else ""
        )

    return subprocess.run(
        ["node", "-e", code, *map(str, files)],
        cwd=str(frontend),
        env=env,
        text=True,
        capture_output=True,
    )


def verify(frontend: Path, backend: Path, *, skip_build: bool = False):
    print("=" * 118)
    print("VERIFY COMPUTER VISION V0.14.0 — REBASED TREE")
    print("=" * 118)

    failures = 0

    def read(path):
        return path.read_text(encoding="utf-8")

    models = read(backend / "app/services/vision_app/models.py")
    streaming_path = backend / "app/services/vision_app/streaming_runtime.py"
    streaming = read(streaming_path) if streaming_path.exists() else ""
    manager = read(backend / "app/services/vision_app/automation_manager.py")
    registry = read(backend / "app/services/vision_app/endpoint_registry.py")
    api = read(backend / "app/api/v1/endpoints/vision_app_api.py")
    page = read(frontend / "src/Pages/ComputerVisionPage.tsx")
    stream_ui_path = frontend / "src/components/ComputerVision/StreamingWorkspace.tsx"
    stream_ui = read(stream_ui_path) if stream_ui_path.exists() else ""
    camera_ui = read(frontend / "src/components/ComputerVision/CameraDeclarationWorkspace.tsx")
    ts_api = read(frontend / "src/api/visionAppApi.ts")
    context_gen = read(frontend / "tools/generate_llm_context_map.py")

    checks = [
        (
            "Program schema v7 + workspace Soft Trigger",
            "version: int = 7" in models
            and "class SoftTriggerConfig" in models
            and "soft_trigger: SoftTriggerConfig" in models,
        ),
        (
            "Basler persistent backend streaming runtime",
            "class StreamingServiceManager" in streaming
            and "StartGrabbing" in streaming
            and "GrabStrategy_LatestImageOnly" in streaming,
        ),
        (
            "Soft Trigger threshold/hysteresis runtime",
            "trigger_pixel_count" in streaming
            and "reset_pixel_count" in streaming
            and "_process_soft" in streaming,
        ),
        (
            "Lazy browser stream transport",
            "after_sequence" in api
            and "status_code=204" in api
            and "streamLatestFrame" in ts_api,
        ),
        (
            "ONLINE arms/disarms workspace Soft Triggers",
            "self.streaming.arm_program(program)" in manager
            and "self.streaming.disarm_program(program)" in manager,
        ),
        (
            "Streaming module UI installed",
            "StreamingWorkspace" in page
            and "Streaming" in page
            and "LIVE SENSOR METRICS" in stream_ui,
        ),
        (
            "Camera Declare no longer owns continuous preview",
            "Live Preview" not in camera_ui
            and "Continuous streaming" in camera_ui,
        ),
        (
            "HTTP/Raspberry Pi streaming stays pending",
            "Streaming transport pending" in camera_ui
            and "HTTP/Raspberry Pi streaming is intentionally pending" in stream_ui,
        ),
        (
            "Streaming + Soft Trigger IDE endpoints",
            "stream_fps" in registry
            and "soft_trigger.pixel_count" in registry
            and "soft_triggered" in registry,
        ),
        (
            "Full keyboard.key namespace",
            'path="keyboard.key"' in registry
            and 'f"keyboard.{key}"' in registry
            and "key.NUM_" in registry,
        ),
        (
            "Physical keyboard uses KeyboardEvent.code mapping",
            "Key[A-Z]" in page
            and "key.NUM_" in page
            and "key.NUMPAD_" in page,
        ),
        (
            "Strict workspace isolation still present",
            "masterLoadSeq" in page
            and "freshWorkspace" in page,
        ),
        (
            "v0.14 regression test installed",
            (backend / "tests/vision_app/test_vision_app_v1400.py").exists(),
        ),
        (
            "v0.14 handoff installed",
            (
                frontend
                / "docs/llm_context/updates/v1400_streaming_soft_trigger.md"
            ).exists(),
        ),
        (
            "Context generator documents v0.14",
            "v0.14" in context_gen
            and "Soft Trigger" in context_gen,
        ),
    ]

    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    py_files = [
        real_path(frontend, backend, virtual)
        for virtual in list(MODIFIED) + list(CREATED)
        if virtual.endswith(".py")
    ]
    py_bad = []

    for path in py_files:
        try:
            py_compile.compile(str(path), doraise=True)
        except Exception as exc:
            py_bad.append(f"{path}: {exc}")

    if py_bad:
        print("[FAIL] Python syntax")
        for issue in py_bad:
            print("  -", issue)
        failures += len(py_bad)
    else:
        print(f"[OK] Python syntax ({len(py_files)} changed/new Python files)")

    if (
        importlib.util.find_spec("pytest") is not None
        and (backend / "tests/vision_app").exists()
    ):
        env = dict(os.environ)
        env["PYTHONPATH"] = str(backend) + (
            os.pathsep + env["PYTHONPATH"]
            if env.get("PYTHONPATH")
            else ""
        )

        proc = subprocess.run(
            [
                sys.executable,
                "-m",
                "pytest",
                "-q",
                "tests/vision_app",
            ],
            cwd=str(backend),
            env=env,
            text=True,
            capture_output=True,
        )

        if proc.returncode == 0:
            print("[OK] Vision App regression tests")
            if proc.stdout.strip():
                print(proc.stdout.strip())
        else:
            print("[FAIL] Vision App regression tests")
            print(
                (
                    proc.stdout
                    + "\n"
                    + proc.stderr
                ).strip()
            )
            failures += 1
    else:
        print("[SKIP] pytest / Vision App tests unavailable")

    ts = typescript_transpile(frontend)
    ts_text = (ts.stdout + "\n" + ts.stderr).strip()

    if ts.returncode == 0:
        print("[OK] TypeScript syntax/transpile")
    elif (
        "Cannot find module 'typescript'" in ts_text
        or "MODULE_NOT_FOUND" in ts_text
    ):
        print("[SKIP] TypeScript module unavailable to Node")
    else:
        print("[FAIL] TypeScript syntax/transpile")
        print(ts_text)
        failures += 1

    if (
        not skip_build
        and (frontend / "package.json").exists()
        and (frontend / "node_modules").exists()
    ):
        proc = subprocess.run(
            ["npm", "run", "build"],
            cwd=str(frontend),
        )

        if proc.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")

    try:
        regenerate_context(frontend, backend)
        print("[OK] LLM context regeneration")
    except Exception as exc:
        print(f"[FAIL] Context regeneration: {exc}")
        failures += 1

    if failures:
        print(
            f"[FAIL] v0.14.0 rebase verification finished "
            f"with {failures} issue(s)."
        )
        return 1

    print(
        "[OK] Computer Vision v0.14.0 "
        "Streaming / Soft Trigger rebase verified."
    )
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "command",
        choices=["scan", "apply", "verify"],
    )
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument(
        "--skip-build",
        action="store_true",
    )
    args = parser.parse_args()

    try:
        frontend, backend = resolve_roots(
            args.frontend,
            args.backend,
        )

        if args.command == "scan":
            return scan(frontend, backend)

        if args.command == "apply":
            return apply(frontend, backend)

        return verify(
            frontend,
            backend,
            skip_build=args.skip_build,
        )

    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
